{
  "name": "Newport XPS精密运动控制器",
  "name_en": "Newport XPS Precision Motion Controller",
  "manufacturer": "Newport",
  "description": "这是一种用于精密位移与定位实验的网络化运动控制器，可驱动和协调电动位移台、线性/旋转执行器等设备。它常用于光学对准、样品定位、扫描测量和自动化实验平台，并可在控制器内部保存配置、程序或日志等文件供网络管理。",
  "description_en": "This is a networked precision motion controller used for laboratory positioning and motion applications. It drives and coordinates motorized stages and linear or rotary actuators, and is commonly used for optical alignment, sample positioning, scanning measurements, and automated experimental platforms. The controller can also store configuration, program, or log files for network-based file management.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到控制器的FTP文件服务。",
      "description_en": "Connect to the controller's FTP file service."
    },
    {
      "action_name": "auto-delete",
      "description": "删除控制器上的文件。",
      "description_en": "Delete a file stored on the controller."
    },
    {
      "action_name": "auto-getlines",
      "description": "读取控制器上文本文件的内容。",
      "description_en": "Read the contents of a text file stored on the controller."
    },
    {
      "action_name": "auto-list",
      "description": "列出控制器当前或指定目录中的文件。",
      "description_en": "List files in the controller's current or specified directory."
    },
    {
      "action_name": "auto-put",
      "description": "向控制器上传文本内容并保存为文件。",
      "description_en": "Upload text content to the controller and save it as a file."
    },
    {
      "action_name": "auto-save",
      "description": "将控制器上的文件下载并保存到本地。",
      "description_en": "Download a file from the controller and save it locally."
    },
    {
      "action_name": "auto-cwd",
      "description": "切换控制器上的当前工作目录。",
      "description_en": "Change the current working directory on the controller."
    }
  ],
  "tag_hints": [
    "Newport XPS",
    "precision motion control",
    "motorized stage controller",
    "positioning stages",
    "optical alignment",
    "networked instrument control",
    "FTP file management"
  ]
}

